css:
.incubatorsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #21183a;
    background: linear-gradient(160deg, #f3f0fb 0%, #ece7f7 100%);
    border-radius: 18px;
}

.incubatorsim-container * {
    box-sizing: border-box;
}

.incubatorsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #2b1a5e 0%, #4226a0 50%, #6c3fd6 100%);
    color: #f6f2ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 32px rgba(43, 26, 94, 0.34);
}

.incubatorsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.incubatorsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #d8c9ff;
    background: rgba(255, 255, 255, 0.13);
    padding: 5px 14px;
    border-radius: 999px;
}

.incubatorsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ece4ff;
}

.incubatorsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #3a2a72;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.incubatorsim-period-counter #currentDay,
.incubatorsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #2b1a5e;
}

.incubatorsim-round-name {
    background: #e0d6fb;
    color: #2b1a5e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.incubatorsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4a12;
    background: #fceadb;
    padding: 4px 12px;
    border-radius: 999px;
}

.incubatorsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.incubatorsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e1d9f3;
    box-shadow: 0 4px 14px rgba(43, 26, 94, 0.07);
    border-top: 4px solid #6c3fd6;
}

.incubatorsim-card-survival { border-top-color: #128a5a; }
.incubatorsim-card-funding { border-top-color: #c98a16; }
.incubatorsim-card-efficiency { border-top-color: #4226a0; }
.incubatorsim-card-budget { border-top-color: #2f6fb0; }

.incubatorsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a5d8c;
}

.incubatorsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2b1a5e;
}

.incubatorsim-card-survival .incubatorsim-value { color: #128a5a; }
.incubatorsim-card-funding .incubatorsim-value { color: #c98a16; }
.incubatorsim-card-efficiency .incubatorsim-value { color: #4226a0; }
.incubatorsim-card-budget .incubatorsim-value { font-size: 1.7rem; color: #2f6fb0; }

.incubatorsim-sublabel {
    font-size: 0.76rem;
    color: #7d709c;
    line-height: 1.35;
}

.incubatorsim-survival-fail .incubatorsim-value { color: #c0392b; }
.incubatorsim-survival-target .incubatorsim-value { color: #128a5a; }
.incubatorsim-funding-fail .incubatorsim-value { color: #c0392b; }
.incubatorsim-funding-target .incubatorsim-value { color: #128a5a; }

.incubatorsim-support-over { border-top-color: #c0392b; }
.incubatorsim-support-over .incubatorsim-value { color: #c0392b; }

.incubatorsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #2b1a5e;
    color: #efe9ff;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.incubatorsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.incubatorsim-budget-over {
    background: #7a1f1f;
}

.incubatorsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #6c3fd6;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(43, 26, 94, 0.06);
}

.incubatorsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.incubatorsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2b1a5e;
    margin-bottom: 6px;
}

.incubatorsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a2f52;
}

.incubatorsim-briefing-text strong { color: #128a5a; }
.incubatorsim-briefing-text em { color: #9a4a12; font-style: italic; }

.incubatorsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e1d9f3;
    box-shadow: 0 4px 14px rgba(43, 26, 94, 0.07);
}

.incubatorsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2b1a5e;
    border-bottom: 2px solid #ece7f7;
    padding-bottom: 8px;
}

.incubatorsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2e2350;
    margin: 14px 0 6px;
}

.incubatorsim-container select,
.incubatorsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdbff0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf8ff;
    color: #21183a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.incubatorsim-container select:focus,
.incubatorsim-container input[type="number"]:focus {
    outline: none;
    border-color: #6c3fd6;
    box-shadow: 0 0 0 3px rgba(108, 63, 214, 0.16);
}

.incubatorsim-container select option {
    background-color: #ffffff;
    color: #21183a;
}

.incubatorsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6c3fd6;
}

.incubatorsim-range-readout,
.incubatorsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4226a0;
    margin-top: 4px;
}

.incubatorsim-range-readout span:last-child,
.incubatorsim-alloc-readout span:nth-child(2) {
    color: #128a5a;
    font-weight: 800;
}

.incubatorsim-hint {
    font-size: 0.8rem;
    color: #7d709c;
    margin-top: 4px;
    line-height: 1.4;
}

.incubatorsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.incubatorsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f2ff;
    border: 1px solid #e4dbf6;
    border-radius: 9px;
    padding: 8px 12px;
}

.incubatorsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2e2350;
}

.incubatorsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.incubatorsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.incubatorsim-container .btn-primary {
    background: linear-gradient(135deg, #128a5a 0%, #6c3fd6 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(108, 63, 214, 0.30);
}

.incubatorsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.incubatorsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdbff0;
    color: #6a5d8c;
}

.incubatorsim-coach {
    background: #2b1a5e;
    color: #efe9ff;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(43, 26, 94, 0.24);
}

.incubatorsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #b79bf0;
    margin-bottom: 8px;
}

.incubatorsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.incubatorsim-coach-body strong { color: #8be0b3; }
.incubatorsim-coach-body em { color: #ffd08a; font-style: italic; }

.incubatorsim-history,
.incubatorsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e1d9f3;
    box-shadow: 0 4px 14px rgba(43, 26, 94, 0.07);
}

.incubatorsim-history h3,
.incubatorsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2b1a5e;
}

.incubatorsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2e2350;
}

.incubatorsim-container table#usfHistoryTable th {
    background: #efeafb;
    color: #2b1a5e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd1f4;
}

.incubatorsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ebf9;
}

.incubatorsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8ff;
}

.incubatorsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .incubatorsim-container {
        padding: 14px;
    }
    .incubatorsim-header h1 {
        font-size: 1.7rem;
    }
    .incubatorsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .incubatorsim-value {
        font-size: 2rem;
    }
    .incubatorsim-card-budget .incubatorsim-value {
        font-size: 1.4rem;
    }
    .incubatorsim-clock {
        margin-left: 0;
    }
    .incubatorsim-period-counter {
        font-size: 0.88rem;
    }
    .incubatorsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .incubatorsim-alloc-row {
        flex-wrap: wrap;
    }
    .incubatorsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .incubatorsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion-message card (appended; self-contained, purple palette) */
.incubatorsim-cm { background:#faf8ff; color:#21183a; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(43,26,94,0.18); }
.incubatorsim-cm-head { text-align:center; border-bottom:1px solid #e1d9f3; padding-bottom:14px; margin-bottom:16px; }
.incubatorsim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#6c3fd6; font-weight:700; }
.incubatorsim-cm-scorewrap { margin:8px 0 2px; }
.incubatorsim-cm-score { font-size:52px; font-weight:800; color:#4226a0; line-height:1; }
.incubatorsim-cm-score-max { font-size:20px; color:#8a7fb0; font-weight:600; }
.incubatorsim-cm-grade { font-size:19px; font-weight:700; color:#21183a; margin-top:4px; }
.incubatorsim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.incubatorsim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.incubatorsim-cm-met { background:#cdeede; color:#0f6b45; }
.incubatorsim-cm-fail { background:#f6dcd6; color:#a3311f; }
.incubatorsim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.incubatorsim-cm-metric { background:#efe9ff; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.incubatorsim-cm-metric-val { font-size:22px; font-weight:800; color:#2b1a5e; }
.incubatorsim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#6c3fd6; margin-top:3px; }
.incubatorsim-cm-insights { background:#efe9ff; border-radius:10px; padding:14px 18px; }
.incubatorsim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#6c3fd6; font-weight:700; margin-bottom:8px; }
.incubatorsim-cm-insights ul { margin:0; padding-left:18px; }
.incubatorsim-cm-insights li { font-size:14px; line-height:1.5; color:#2e2350; margin-bottom:7px; }

