                    grade_zombie:           `Cumplido Sobre el Papel — Riesgo Zombi`,
                    grade_survonly:         `Supervivencia Cumplida, Financiación Corta`,
                    grade_fundonly:         `Financiación Cumplida, Supervivencia Corta`,
                    grade_improving:        `Mejora pero Insuficiente`,
                    grade_lost:             `Mandato Perdido`,
